_SHEET = None
_CACHE = {}


def width(text, scale=1):
    return sum(WIDTHS[scale][c] for c in text)


def draw_text(screen, text, x, y, scale=1, inverted=False):
    global _SHEET
    for c in text:
        key = (scale, int(inverted), c)
        if key not in _CACHE:
            if _SHEET is None:
                _SHEET = image.load('font.png')
            _CACHE[key] = _SHEET.window(*GLYPHS[key])
        screen.blit(_CACHE[key], vec2(x, y))
        x += WIDTHS[scale][c]
